	/**
	 * Alle verfügbaren Icons.
	 *
	 * @return array<string,array{label:string,viewbox:string,path:string}>
	 */
	public static function all(): array {
		static $icons = null;
		if ( null !== $icons ) {
			return $icons;
		}
		$icons = array();
		foreach ( self::ICONS as $key => $icon ) {
			$icons[ $key ] = array(
				'label'   => $icon[0],
				'viewbox' => $icon[1],
				'path'    => $icon[2],
			);
		}

		/**
		 * Eigene Icons ergänzen: array( 'schluessel' => array( 'label' => …, 'viewbox' => '0 0 512 512', 'path' => 'M…' ) ).
		 * Nur einfache SVG-Pfade (Attribut d) werden übernommen.
		 *
		 * @param array<string,array{label:string,viewbox:string,path:string}> $icons Icons.
		 */
		$filtered = (array) apply_filters( 'b83_osm_icons', $icons );
		$icons    = array();
		foreach ( $filtered as $key => $icon ) {
			$key = sanitize_key( (string) $key );
			if ( '' === $key || ! is_array( $icon ) ) {
				continue;
			}
			$viewbox = (string) ( $icon['viewbox'] ?? '' );
			$path    = (string) ( $icon['path'] ?? '' );
			if ( 1 !== preg_match( '/^[\d.\s-]+$/', $viewbox ) || 1 !== preg_match( '/^[MmLlHhVvCcSsQqTtAaZz\d.,\s-]+$/', $path ) ) {
				continue;
			}
			$icons[ $key ] = array(
				'label'   => (string) ( $icon['label'] ?? $key ),
				'viewbox' => $viewbox,
				'path'    => $path,
			);
		}
		return $icons;
	}

	public static function exists( string $key ): bool {
		return isset( self::all()[ $key ] );
	}

	/** Icon als SVG-Markup (für Backend-Auswahl und Frontend-Pins). */
	public static function svg( string $key ): string {
		$icon = self::all()[ $key ] ?? null;
		if ( null === $icon ) {
			return '';
		}
		return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="' . esc_attr( $icon['viewbox'] ) . '" aria-hidden="true" focusable="false"><path fill="currentColor" d="' . esc_attr( $icon['path'] ) . '"/></svg>';
	}
}
